#include <vector>
#include <cstddef>
#include <omp.h>
#include <stdexcept>

void luFactorize(std::vector<double> &A, size_t N) {
    if (N == 0) return;
    if (A.size() != N * N) throw std::invalid_argument("luFactorize: A.size() must be N*N");

    for (size_t k = 0; k < N; ++k) {
        const double pivot = A[k * N + k];
        if (pivot == 0.0) {
            // No pivoting implemented; a zero pivot would cause division by zero.
            throw std::runtime_error("luFactorize: zero pivot encountered (no pivoting implemented)");
        }

        // Compute multipliers for L column k: A[i,k] /= A[k,k] for i>k
        #pragma omp parallel for schedule(static)
        for (std::ptrdiff_t ii = static_cast<std::ptrdiff_t>(k + 1); ii < static_cast<std::ptrdiff_t>(N); ++ii) {
            A[static_cast<size_t>(ii) * N + k] /= pivot;
        }

        // Update trailing submatrix: A[i,j] -= A[i,k] * A[k,j] for i>k, j>k
        // Parallelize over rows i; each thread updates disjoint row segments (no races).
        #pragma omp parallel for schedule(static)
        for (std::ptrdiff_t ii = static_cast<std::ptrdiff_t>(k + 1); ii < static_cast<std::ptrdiff_t>(N); ++ii) {
            const size_t i = static_cast<size_t>(ii);
            const double lik = A[i * N + k];
            const size_t rowBase = i * N;
            const size_t kBase   = k * N;
            for (size_t j = k + 1; j < N; ++j) {
                A[rowBase + j] -= lik * A[kBase + j];
            }
        }
    }
}
